
(()=>{
const root=document.getElementById('portfolio-review-oct');
const photos={ss:'data:image/jpeg;base64,',bb:'data:image/jpeg;base64,'};
photos.slope='data:image/jpeg;base64,';
const cases={
 plan:[{name:'SSketch',label:'요구사항 · 게임 규칙',title:'문서와 코드가 같은 말을 하게.',image:'ss',scope:'요구사항 명세 · 진척 관리 · 규칙 설계',context:'4인 멀티플레이 파티 게임 · 6인 팀 · 2026.08–09',problem:'기획 문서와 실제 구현 상태가 따로 움직여, 완료 여부를 같은 기준으로 판단하기 어려웠습니다.',decision:'요구사항 250건을 명세하고 develop 코드와 대조해 진척을 재판정했습니다. 그림의 원작자·운반자·집 주인을 구분해 소유권 규칙도 정리했습니다.',result:'12개 대분류별 진행 상태와 담당 범위를 문서로 관리했습니다. 2026.09.26 코드 기준 재점검에서 진척률은 62%였습니다.',evidence:'요구사항 요약 시트 · 그림 소유권 도식 · 설정 창 프로토타입',boundary:'설정 창·규칙 코드·서버 방 코드 기능 구현에는 AI 코딩 도구를 활용했습니다. 프로젝트 원안은 팀원에게서 출발했습니다.'},
 {name:'BodyBuilder',label:'UGC 정책 · 공개 조건',title:'직접 깬 맵만 공개할 수 있도록.',image:'bb',scope:'창작마당 명세 · 정책 · 프론트엔드',context:'웹캠 기반 4인 협동 웹 게임 · 6인 팀 · 2026.07–08',problem:'유저가 만든 맵의 자유도를 열면서도, 다른 이용자가 플레이할 수 있는 품질을 확보해야 했습니다.',decision:'제작자 클리어를 공개 조건으로 정하고 편집·검증·공개 상태를 분리했습니다. 공식 맵 6개 실측을 기준으로 제작 한도를 정했습니다.',result:'구현명세서와 프론트·백엔드 작업지시서를 작성하고 프론트엔드를 구현했습니다.',evidence:'맵 에디터 · 공개 조건 명세 · 공식 맵 실측',boundary:'백엔드는 작업지시서에 따라 다른 팀원이 구현했습니다. 프론트엔드에 일부 AI 코딩 도구를 활용했습니다.'}],
 qa:[{name:'BodyBuilder',label:'재현 조건 · 회귀 검증',title:'걷는데 왜 ‘추락’으로 보였을까.',image:'slope',scope:'상태 판정 명세 · 수정 · 테스트 작성',context:'웹캠 기반 4인 협동 웹 게임 · 6인 팀 · 2026.07–08',problem:'경사면을 걸어 내려가는 캐릭터가 계속 추락 상태로 표시됐습니다.',decision:'45° 경사에서 수직 속도는 약 134였지만 프레임당 변화량은 거의 0이었습니다. 절대 속도 대신 변화량과 최소 지속시간으로 판정하고 맵 스케일을 정규화했습니다.',result:'2026.10.06 재실행 기록에서 회귀 테스트 14/14 통과. 경사 보행·자유낙하·두 맵 스케일 조건을 확인했습니다.',evidence:'수정 후 플레이 화면 · 재현 조건 · 회귀 테스트 기록',boundary:'본인이 작성한 초기 명세의 임계값 문제를 추적하고 수정했습니다. 구현에 일부 AI 코딩 도구를 활용했습니다.'},
 {name:'SSketch',label:'플레이 피드백 · 개선 제안',title:'점수보다 관계가 평가를 바꿀 때.',image:'ss',scope:'피드백 분석 · 문제 정의 · 대응안 정리',context:'4인 멀티플레이 파티 게임 · 6인 팀 · 2026.08–09',problem:'익명 평가를 의도했지만 이용자의 관계와 담합이 점수에 개입했습니다.',decision:'피드백 30여 건에서 평가 담합 관련 의견 약 11건을 묶고, 점수를 낮게 주도록 유도하는 압력을 분석했습니다.',result:'대응 방향을 네 갈래로 정리하고 우선순위를 제안했습니다. 개선안 적용 후 효과 측정은 별도 확인이 필요합니다.',evidence:'피드백 분류 기록 · 평가 구조 분석 · 대응안',boundary:'피드백 분석과 대응안 제안을 담당했습니다. 제안 후 적용 여부와 효과는 검증 범위에 포함하지 않았습니다.'}]
};
const names={plan:'기획',qa:'게임 분석·QA'};
function nav(current){return ['home','plan','qa','about'].map(k=>`<button class="navitem" data-page="${k}" aria-pressed="${current===k}">${({home:'홈',plan:'기획',qa:'게임 분석·QA',about:'소개·연락'})[k]}</button>`).join('')}
root.querySelectorAll('.p-site').forEach((site,index)=>{
 let state={page:'home',role:'plan',selected:0};
 const concept=['설명서 리파인','채용 브리핑','케이스 저널'][index];
 function restore(saved){if(saved?.concept===concept && ['home','plan','qa','about','detail'].includes(saved.page)){state={page:saved.page,role:saved.role==='게임 분석·QA'?'qa':'plan',selected:saved.selected===1?1:0};}}
 restore(window.openai?.widgetState?.modelContent);
 window.addEventListener('openai:set_globals',e=>{restore(e.detail?.globals?.widgetState?.modelContent);render();});
 function cards(role){return `<div class="pair">${cases[role].map((c,i)=>`<article class="work"><img src="${photos[c.image]}" alt="${c.image==='ss'?'SSketch 그림 소유권 설계 도식':c.image==='slope'?'BodyBuilder 경사면 보행 플레이 화면':'BodyBuilder 창작마당 맵 에디터'}"><div class="work-copy"><small>${c.name} / ${c.label}</small><h3>${c.title}</h3><p class="sub">${c.scope}</p><button class="textlink" data-case="${i}" data-role="${role}">판단과 근거 읽기 ↗</button></div></article>`).join('')}</div>`}
 function tabs(){return `<div class="tabs">${['plan','qa'].map(r=>`<button class="navitem" data-rolepick="${r}" aria-pressed="${state.role===r}">${names[r]}</button>`).join('')}</div>`}
 function render(){let body='';
 if(state.page==='home'){
 let hero=index===0?'<div class="kicker">KIM SI HOO / PORTFOLIO</div><h1>김시후<br>게임·서비스 기획, 게임 분석·QA</h1><p class="sub">규칙과 요구사항을 설계하고,<br>플레이에서 발견한 문제를 재현 조건으로 남깁니다.</p>':index===1?'<div class="kicker">김시후 · 게임·서비스 기획 / 게임 분석·QA</div><h1>만들 기준을 세우고,<br>문제의 원인을 찾습니다.</h1><p class="sub">요구사항 명세부터 규칙 설계,<br>재현 조건과 회귀 검증까지.</p>':'<div class="kicker">KIM SI HOO — SELECTED CASES</div><h1>판단은 간결하게.<br>근거는 구체적으로.</h1><p>김시후 · 게임·서비스 기획 / 게임 분석·QA</p>';
 body=`<section class="hero"><div>${hero}<div class="actions"><button class="action primary" data-page="plan">기획 사례 보기</button><button class="action" data-page="qa">게임 분석·QA 보기</button><a class="textlink" href="mailto:kimshlife@naver.com">이메일 ↗</a></div></div>${index===1?'<aside class="intro-proof"><small>경험의 근거</small><p><b>250건</b> · SSketch 요구사항 명세</p><p><b>14/14</b> · BodyBuilder 회귀 테스트<br><small>2026.10.06 재실행 기록</small></p><p>제조업 수입검사 경력 2년 2개월</p></aside>':''}</section>`;
 if(index===0)body+=`<div class="pair"><section class="rolebox"><div class="kicker">PLANNING</div><h2>기획</h2><p>규칙·수치·요구사항을<br>실행 가능한 명세로 정리합니다.</p><button class="textlink" data-page="plan">SSketch · BodyBuilder →</button></section><section class="rolebox"><div class="kicker">GAME ANALYSIS / QA</div><h2>게임 분석·QA</h2><p>문제의 조건을 좁히고<br>수정과 검증의 근거를 남깁니다.</p><button class="textlink" data-page="qa">BodyBuilder · SSketch →</button></section></div>`;
 body+=`<section class="p-section"><div class="p-section-head"><h2>${index===2?'선별한 두 개의 기록':'대표 사례'}</h2><small>${names[state.role]}</small></div>${tabs()}${cards(state.role)}</section><section class="p-section proofline"><span>국립금오공과대학교 경영학과</span><span>SSAFY 15기</span><button class="textlink" data-page="about">이력과 연락처 →</button></section>`;
 }else if(state.page==='plan'||state.page==='qa'){
 const r=state.page;body=`<section class="role-title"><div class="kicker">김시후 / ${r==='plan'?'PLANNING':'GAME ANALYSIS & QA'}</div><h1>${names[r]}</h1><p class="sub">${r==='plan'?'규칙과 요구사항을 정의하고, 구현할 수 있는 명세로 연결합니다.':'이용자가 겪은 문제를 재현 조건과 검증 근거로 설명합니다.'}</p></section>${cards(r)}<section class="p-section"><h2>더 살펴볼 작업</h2><p class="sub">${r==='plan'?'ProjectRG — 5축 진단과 보충 질문 규칙 / NeonTetrisWars — 회전 제한·락 딜레이 설계':'PEAK 설정 레퍼런스 — 채택·변경·제외 항목 / 카운터사이드 — 애착과 선택 구조 분석'}</p></section>`;
 }else if(state.page==='detail'){
 const c=cases[state.role][state.selected];body=`<button class="textlink" data-page="${state.role}">← ${names[state.role]} 사례</button><div class="kicker">${c.name} / ${c.label}</div><h1>${c.title}</h1><p class="sub">${c.context}</p><div class="facts"><div><small>본인 담당</small>${c.scope}</div><div><small>근거 자료</small>${c.evidence}</div></div><div class="detail-hero"><img src="${photos[c.image]}" alt="${c.image==='ss'?'그림 소유권 설계 도식':c.image==='slope'?'BodyBuilder 경사면 보행 플레이 화면':'BodyBuilder 창작마당 화면'}"><div><h2>어떤 문제였나</h2><p>${c.problem}</p></div></div><div class="story"><b>판단과 행동</b><p>${c.decision}</p></div><div class="story"><b>결과</b><p>${c.result}</p></div><details><summary>담당 범위와 구현 도구</summary><p>${c.boundary}</p></details><button class="textlink" data-other="${c.name}">${c.name}의 ${state.role==='plan'?'게임 분석·QA':'기획'} 사례 보기 →</button>`;
 }else{body='<div class="kicker">ABOUT & CONTACT</div><h1>김시후</h1><p>게임·서비스 기획 / 게임 분석·QA</p><div class="p-section"><h2>주요 이력</h2><div class="story"><b>경력</b><p>제조업 품질보증부 · 수입검사<br>2020.06–2022.07 / 2년 2개월</p></div><div class="story"><b>학력</b><p>국립금오공과대학교 경영학과 학사<br>2018.03–2025.08</p></div><div class="story"><b>교육</b><p>삼성 청년 SW·AI 아카데미 15기<br>2026.01–2026.12 수료 예정</p></div><div class="actions"><a class="action primary" href="mailto:kimshlife@naver.com">kimshlife@naver.com ↗</a><a class="action" href="mailto:kimshlife@naver.com?subject=이력서%20요청">이력서 요청</a></div></div>'}
 site.innerHTML=`<header class="p-head"><button class="brand" data-page="home">${index===2?'Kim Sihoo.':'김시후'}<small>${index===0?'PORTFOLIO / USER MANUAL':'GAME PLANNING & ANALYSIS'}</small></button><nav aria-label="포트폴리오">${nav(state.page)}</nav></header><div class="p-layout">${index===0?`<aside class="p-aside"><div class="kicker">CONTENTS</div>${nav(state.page)}<p class="sub" style="margin-top:50px;font-size:12px">즐겁고, 편리하게,<br>지속가능하도록.</p></aside>`:''}<main class="p-body">${body}<footer class="p-foot"><span>김시후 · Portfolio</span><a href="mailto:kimshlife@naver.com">kimshlife@naver.com</a></footer></main></div>`;
 }
 render();site.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){state.page=b.dataset.page;if(['plan','qa'].includes(state.page))state.role=state.page;}else if(b.dataset.rolepick){state.role=b.dataset.rolepick;}else if(b.dataset.case!==undefined){state.page='detail';state.role=b.dataset.role;state.selected=Number(b.dataset.case);}else if(b.dataset.other){state.role=state.role==='plan'?'qa':'plan';state.selected=cases[state.role].findIndex(c=>c.name===b.dataset.other);}else return;render();window.openai?.setWidgetState?.({modelContent:{concept:['설명서 리파인','채용 브리핑','케이스 저널'][index],page:state.page,role:names[state.role],selected:state.selected},privateContent:{}})?.catch(()=>{});});
 if(globalThis.Tweak){const settings={space:34};new Tweak({container:site,onChange:()=>site.querySelector('.p-body').style.padding=settings.space+'px'}).addSlider(settings,'space',{label:'본문 여백',min:20,max:48,unit:'px'});}
});
})();
